import sqlite3, json, os, re, collections
def db(root, frozen):
    p = json.load(open(root + "/registry.json"))["repos"][0]["db_path"]
    if frozen:
        w = p + "-wal"
        assert not os.path.exists(w) or os.path.getsize(w) == 0, ("manager root WAL not empty", w)
        return sqlite3.connect("file:" + p + "?immutable=1", uri=True)
    return sqlite3.connect("file:" + p + "?mode=ro", uri=True)
def one(c, q, *a): return c.execute(q, a).fetchone()[0]
def normalizer(c):
    [ru] = [r[0] for r in c.execute("select distinct repo_uid from snapshots")]
    def n(v):
        if isinstance(v, str):
            v = v.replace(ru, "<repo>")
            if re.fullmatch(r"indexer:[0-9]+\.[0-9]+\.[0-9]+", v): v = "<indexer>"
        return v
    return lambda row: tuple(n(v) for v in row)
def same(label, x, y):
    if x != y:
        sx, sy = set(x), set(y)
        raise AssertionError((label, len(x), len(y), "before-only", [r for r in x if r not in sy][:3], "after-only", [r for r in y if r not in sx][:3]))
# Schema audit (RULE: every persisted column of a compared table is either compared or named here as excluded; a
# reference column is compared THROUGH the referenced row's stable key or path). A schema-change TRIPWIRE: it fails when the
# store's schema differs from this declaration; it does not by itself prove that each partitioned query exercises every
# declared column — the queries below are written to (NODE_ROW, EDGE_ROW/OTHER, UNRES_ROW, and Q for the from-import edges).
SCHEMA = {
    "nodes": ({"stable_key", "kind", "subtype", "name", "qualified_name", "file_uid", "parent_node_uid", "line_start", "col_start", "line_end", "col_end", "signature", "visibility", "doc_comment", "metadata_json"}, {"node_uid", "snapshot_uid", "repo_uid"}),
    "edges": ({"source_node_uid", "target_node_uid", "type", "resolution", "extractor", "line_start", "col_start", "line_end", "col_end", "metadata_json", "is_type_only"}, {"edge_uid", "snapshot_uid", "repo_uid"}),
    "unresolved_edges": ({"source_node_uid", "target_key", "type", "resolution", "extractor", "category", "classification", "classifier_version", "basis_code", "line_start", "col_start", "line_end", "col_end", "metadata_json"}, {"edge_uid", "snapshot_uid", "repo_uid", "observed_at"}),
}
def audit(c, schema):
    for tname, (cmp, excl) in schema.items():
        cols = {r[1] for r in c.execute("pragma table_info(%s)" % tname)}
        assert cols == cmp | excl and not cmp & excl, ("schema audit: a column is neither compared nor declared excluded", tname, sorted(cols ^ (cmp | excl)))
NODE_ROW = "select n.stable_key, f.path, n.kind, n.subtype, n.name, n.qualified_name, p.stable_key, n.parent_node_uid is not null, n.line_start, n.col_start, n.line_end, n.col_end, n.signature, n.visibility, n.doc_comment, n.metadata_json from nodes n left join files f on f.file_uid=n.file_uid left join nodes p on p.node_uid=n.parent_node_uid"
EDGE_ROW = "select sn.stable_key, tn.stable_key, e.type, e.resolution, e.extractor, e.line_start, e.col_start, e.line_end, e.col_end, e.metadata_json, e.is_type_only from edges e join nodes sn on sn.node_uid=e.source_node_uid join nodes tn on tn.node_uid=e.target_node_uid"
UNRES_ROW = "select sn.stable_key, u.target_key, u.type, u.resolution, u.extractor, u.category, u.classification, u.classifier_version, u.basis_code, u.line_start, u.col_start, u.line_end, u.col_end, u.metadata_json from unresolved_edges u join nodes sn on sn.node_uid=u.source_node_uid"
def rows(c, q): n = normalizer(c); return sorted((n(r) for r in c.execute(q)), key=repr)
B = db("/private/tmp/PYTHON-SUBMODULE-IMPORT-1-django-before", True)
A = db("/private/tmp/PYTHON-SUBMODULE-IMPORT-1-django-after", False)
Q = """select sf.path, e.line_start, e.col_start, json_extract(e.metadata_json,'$.specifier'), json_extract(e.metadata_json,'$.importedName'), json_extract(e.metadata_json,'$.identifier'), sn.stable_key, tf.path, tn.stable_key, e.resolution, json_extract(e.metadata_json,'$.basis'), json_extract(e.metadata_json,'$.alternateTarget'), e.metadata_json, e.extractor, e.line_end, e.col_end, e.is_type_only from edges e join nodes sn on sn.node_uid=e.source_node_uid join files sf on sf.file_uid=sn.file_uid join nodes tn on tn.node_uid=e.target_node_uid join files tf on tf.file_uid=tn.file_uid where e.type='IMPORTS' and json_extract(e.metadata_json,'$.importedName') is not null"""
def edges(c):
    n = normalizer(c); out, meta, fixed = {}, {}, {}
    for sp, ln, col, spec, name, ident, ssk, tp, tsk, res, basis, alt, mj, ext, le, ce, ito in c.execute(Q):
        k = (sp, ln, col, spec, name, ident, n((ssk,))[0]); assert k not in out, ("edge identity not unique", k); out[k] = (tp, n((tsk,))[0], res, basis, alt); meta[k] = json.loads(mj); fixed[k] = n((ext, le, ce, ito))
    return out, meta, fixed
# the amended RG-REQ-006-L04 rule, recomputed on the BEFORE store (SLICE_DOC 2.1 step 1)
paths = set(r[0] for r in B.execute("select path from files"))
defs = collections.defaultdict(set)
for name, path in B.execute("select n.name, f.path from nodes n join files f on f.file_uid=n.file_uid where n.kind='SYMBOL' and n.qualified_name=n.name"): defs[path].add(name)
binds = {p: json.loads(j) for p, j in B.execute("select f.path, s.import_bindings_json from file_signals s join files f on f.file_uid=s.file_uid where s.import_bindings_json is not null")}
def submodule_itself(b, d, y):
    spec, imp = b.get("specifier", ""), b.get("importedName")
    if imp is not None: return imp == y and spec in (".", d.replace("/", "."))
    return spec == d.replace("/", ".") + "." + y
def rule(tp, y):
    if not tp.endswith("/__init__.py"): return None
    d = tp[:-len("/__init__.py")]
    sub = next((p for p in (d + "/" + y + "/__init__.py", d + "/" + y + ".py") if p in paths), None)
    if sub is None: return (tp, "symbol")
    if y in defs.get(tp, ()): return (tp, "init-defines")
    ys = [b for b in binds.get(tp, []) if b.get("identifier") == y]
    if any(not submodule_itself(b, d, y) for b in ys): return (tp, "init-binds-other")
    return (sub, "submodule-itself" if ys else "submodule")
assert one(B, "select count(*) from snapshots") == 1 and one(A, "select count(*) from snapshots") == 1, "one snapshot per django store (PSI-C04 runs before PSI-C06's refresh)"
audit(B, SCHEMA); audit(A, SCHEMA)
(EB, MB, XB), (EA, MA, XA) = edges(B), edges(A)
assert set(EB) == set(EA), ("from-import edge identities differ", len(set(EB) ^ set(EA)))
kinds = collections.Counter(); movers = {}
for k, (tp, tsk, res, basis, alt) in EB.items():
    r = rule(tp, k[4])
    if r is None: continue
    kinds[r[1]] += 1
    if r[0] != tp: movers[k] = (r[0], tp)
print("rule on the before-store:", dict(kinds), "| movers:", len(movers), "| from-import edges:", len(EB))
assert len(movers) == 1440, ("before-root sanity: movers", len(movers))
sk = dict(A.execute("select f.path, n.stable_key from nodes n join files f on f.file_uid=n.file_uid where n.kind='FILE'"))
nA = normalizer(A); nsk = {p: nA((v,))[0] for p, v in sk.items()}
bad = []
for k, got in EA.items():
    if k in movers:
        want = (movers[k][0], nsk[movers[k][0]], "inferred", "python_submodule", sk[movers[k][1]])
    else:
        want = (EB[k][0], EB[k][1], EB[k][2], None, None)
    if got != want: bad.append((k, got, want))
assert not bad, ("edges not where the rule puts them", len(bad), bad[:5])
bad_fixed = [k for k in EB if XA[k] != XB[k]]
assert not bad_fixed, ("a from-import edge's extractor, line_end, col_end or is_type_only changed (only target, resolution and the two metadata keys may move)", len(bad_fixed), [(k, XB[k], XA[k]) for k in bad_fixed[:3]])
bad_meta = [k for k in EB if {x: y for x, y in MA[k].items() if x not in ("alternateTarget", "basis")} != MB[k] or (k in movers) != ("alternateTarget" in MA[k] and "basis" in MA[k]) or "basis" in MB[k] or "alternateTarget" in MB[k]]
assert not bad_meta, ("a from-import edge's metadata changed beyond the two added keys", len(bad_meta), [(k, MB[k], MA[k]) for k in bad_meta[:3]])
for sp, ln in (("django/core/handlers/wsgi.py", 5), ("django/shortcuts.py", 13)):
    for k in EB:
        if k[0] == sp and k[1] == ln: print("code-under-analysis", sp + ":" + str(ln), "before", EB[k], "after", EA[k])
def by_type(c): return sorted(c.execute("select e.type, e.resolution, count(*) from edges e join nodes a on a.node_uid=e.source_node_uid where not (e.type='IMPORTS' and a.kind='MODULE') group by 1,2").fetchall())
tb, ta = by_type(B), by_type(A)
print("edges by type/resolution (MODULE->MODULE excluded) before", tb, "after", ta)
want_a = sorted([(t, r, n - (1440 if (t, r) == ("IMPORTS", "static") else 0)) for t, r, n in tb] + [("IMPORTS", "inferred", 1440)])
assert ta == want_a, ("only the 1440 movers change certainty; no other edge moves", ta, want_a)
same("an unresolved row changed (RG-REQ-006-L05)", rows(B, UNRES_ROW), rows(A, UNRES_ROW))
same("a node changed (P-PSI-01)", rows(B, NODE_ROW), rows(A, NODE_ROW))
OTHER = EDGE_ROW + " where not (e.type='IMPORTS' and (sn.kind='MODULE' or json_extract(e.metadata_json,'$.importedName') is not null))"
same("an edge outside the from-imports and the persisted module graph changed (P-PSI-01)", rows(B, OTHER), rows(A, OTHER))
def own(c): return dict(c.execute("select f.path, mn.qualified_name from edges e join nodes mn on mn.node_uid=e.source_node_uid join nodes fn on fn.node_uid=e.target_node_uid join files f on f.file_uid=fn.file_uid where e.type='OWNS' and mn.kind='MODULE'"))
def derived(c):
    o = own(c); s = set()
    for sp, tp, res in c.execute("select sf.path, tf.path, e.resolution from edges e join nodes a on a.node_uid=e.source_node_uid join files sf on sf.file_uid=a.file_uid join nodes b on b.node_uid=e.target_node_uid join files tf on tf.file_uid=b.file_uid where e.type='IMPORTS' and a.kind='FILE' and b.kind='FILE'"):
        if res == "inferred": continue
        m1, m2 = o.get(sp), o.get(tp)
        if m1 and m2 and m1 != m2: s.add((m1, m2))
    return s
def stored(c): return c.execute("select a.qualified_name, b.qualified_name from edges e join nodes a on a.node_uid=e.source_node_uid join nodes b on b.node_uid=e.target_node_uid where e.type='IMPORTS' and a.kind='MODULE' and b.kind='MODULE'").fetchall()
sb, sa = stored(B), stored(A)
assert len(sb) == len(set(sb)) == 2451 and set(sb) == derived(B), "before-root sanity: persisted module edges"
assert len(sa) == len(set(sa)) and set(sa) == derived(A), "an inferred import fed the persisted module graph (RG-REQ-002-L11)"
print("persisted MODULE->MODULE IMPORTS before", len(sb), "after", len(sa), "| lost", len(set(sb) - set(sa)), "gained", len(set(sa) - set(sb)))
assert set(sa) <= set(sb), "a module pair appeared that no certain import supports"
def importers(c, p): return sorted(set(c.execute("select sf.path, e.resolution from edges e join nodes tn on tn.node_uid=e.target_node_uid join files tf on tf.file_uid=tn.file_uid join nodes sn on sn.node_uid=e.source_node_uid join files sf on sf.file_uid=sn.file_uid where e.type='IMPORTS' and tf.path=?", (p,))))
print("base.py importers before", importers(B, "django/core/handlers/base.py"), "after", importers(A, "django/core/handlers/base.py"))
assert importers(A, "django/core/handlers/base.py") == [("django/core/handlers/asgi.py", "inferred"), ("django/core/handlers/wsgi.py", "inferred"), ("django/test/client.py", "static")]
for label, c in (("django before", B), ("django after", A)):
    print(label, "nodes", one(c, "select count(*) from nodes"), "edges", one(c, "select count(*) from edges"), "unresolved", one(c, "select count(*) from unresolved_edges"), "toolchain", one(c, "select toolchain_json from snapshots"))
def dump(c): return rows(c, NODE_ROW), rows(c, EDGE_ROW), rows(c, UNRES_ROW)
FB, FA = db("/private/tmp/PYTHON-SUBMODULE-IMPORT-1-fraktag-before", True), db("/private/tmp/PYTHON-SUBMODULE-IMPORT-1-fraktag-after", False)
assert one(FB, "select count(*) from snapshots") == 1 and one(FA, "select count(*) from snapshots") == 1, "one snapshot per FRAKTAG store"
audit(FB, SCHEMA); audit(FA, SCHEMA)
nb_, eb_, ub_ = dump(FB); na_, ea_, ua_ = dump(FA)
print("fraktag before nodes/edges/unresolved", len(nb_), len(eb_), len(ub_), "after", len(na_), len(ea_), len(ua_))
same("FRAKTAG nodes differ - the Python stage leaked", nb_, na_)
same("FRAKTAG edges differ - the Python stage leaked", eb_, ea_)
same("FRAKTAG unresolved rows differ - the Python stage leaked", ub_, ua_)
print("PSI-C04 store oracles ok")
